import React, { useState } from 'react';

const commonDrugs = [
  'Paracetamol 500mg', 'Amoxicillin 250mg', 'Amoxicillin 500mg',
  'Ciprofloxacin 500mg', 'Metronidazole 400mg', 'Coartem',
  'Vitamin C 1000mg', 'Ibuprofen 400mg', 'ORS', 'Omeprazole 20mg',
  'Doxycycline 100mg', 'Azithromycin 500mg',
];

const NewPrescription = ({ patient, doctorName, onSubmit, onCancel }) => {
  const [diagnosis, setDiagnosis]       = useState('');
  const [selectedDrugs, setSelectedDrugs] = useState([]);
  const [notes, setNotes]               = useState('');
  const [error, setError]               = useState('');

  const toggleDrug = (drug) => {
    setSelectedDrugs((prev) =>
      prev.includes(drug) ? prev.filter((d) => d !== drug) : [...prev, drug]
    );
    setError('');
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!diagnosis.trim()) {
      setError('Please enter a diagnosis.');
      return;
    }
    if (selectedDrugs.length === 0) {
      setError('Please select at least one drug.');
      return;
    }

    onSubmit({
      patientId:   patient.id,
      patientName: patient.name,
      doctorName,
      diagnosis,
      drugs: selectedDrugs,
      notes,
      date: new Date().toISOString(),
    });
  };

  return (
    <div>
      {/* Header */}
      <div className="d-flex align-items-center gap-3 mb-4">
        <button
          onClick={onCancel}
          style={{
            background: 'none',
            border: '1px solid #dee2e6',
            borderRadius: '6px',
            padding: '0.3rem 0.7rem',
            cursor: 'pointer',
            fontSize: '0.85rem',
          }}
        >
          ← Back
        </button>
        <div>
          <h2 style={{ fontWeight: 700, fontSize: '1.2rem', margin: 0 }}>
            ✏️ New Prescription
          </h2>
          <p style={{ color: 'var(--muted)', fontSize: '0.82rem', margin: 0 }}>
            Writing for: <strong>{patient.name}</strong> ({patient.id})
          </p>
        </div>
      </div>

      <div className="row g-3">
        {/* Left — Form */}
        <div className="col-12 col-lg-7">
          <div className="card-custom">
            <form onSubmit={handleSubmit} noValidate>

              {/* Patient Info (read-only) */}
              <div
                className="mb-4 p-3"
                style={{
                  backgroundColor: '#f0fff4',
                  borderRadius: '8px',
                  border: '1px solid #b7ebc8',
                  fontSize: '0.85rem',
                }}
              >
                <div style={{ fontWeight: 700, marginBottom: '0.3rem' }}>
                  Patient Information
                </div>
                <div style={{ color: 'var(--muted)' }}>
                  <span>👤 {patient.name}</span>&nbsp;·&nbsp;
                  <span>{patient.gender}</span>&nbsp;·&nbsp;
                  <span style={{ textTransform: 'capitalize' }}>{patient.patientType}</span>
                  {patient.department && <span> · {patient.department}</span>}
                </div>
              </div>

              {/* Doctor (read-only) */}
              <div className="mb-3">
                <label className="form-label fw-semibold" style={{ fontSize: '0.88rem' }}>
                  Doctor
                </label>
                <input
                  type="text"
                  className="form-control form-control-sm"
                  value={doctorName}
                  readOnly
                  style={{ backgroundColor: '#f8f9fa' }}
                />
              </div>

              {/* Diagnosis */}
              <div className="mb-3">
                <label className="form-label fw-semibold" style={{ fontSize: '0.88rem' }}>
                  Diagnosis <span style={{ color: '#dc3545' }}>*</span>
                </label>
                <textarea
                  className="form-control form-control-sm"
                  rows={2}
                  placeholder="e.g. Malaria, Upper Respiratory Tract Infection"
                  value={diagnosis}
                  onChange={(e) => {
                    setDiagnosis(e.target.value);
                    setError('');
                  }}
                />
              </div>

              {/* Drug Selection */}
              <div className="mb-3">
                <label className="form-label fw-semibold" style={{ fontSize: '0.88rem' }}>
                  Prescribed Drugs <span style={{ color: '#dc3545' }}>*</span>
                </label>
                <div
                  style={{
                    display: 'flex',
                    flexWrap: 'wrap',
                    gap: '0.5rem',
                    padding: '0.75rem',
                    backgroundColor: '#f8f9fa',
                    borderRadius: '8px',
                    border: '1px solid #dee2e6',
                  }}
                >
                  {commonDrugs.map((drug) => (
                    <button
                      key={drug}
                      type="button"
                      onClick={() => toggleDrug(drug)}
                      style={{
                        padding: '0.3rem 0.75rem',
                        borderRadius: '999px',
                        fontSize: '0.78rem',
                        fontWeight: 600,
                        cursor: 'pointer',
                        border: '1px solid',
                        transition: 'all 0.15s',
                        backgroundColor: selectedDrugs.includes(drug) ? '#198754' : '#fff',
                        color:           selectedDrugs.includes(drug) ? '#fff'    : '#495057',
                        borderColor:     selectedDrugs.includes(drug) ? '#198754' : '#dee2e6',
                      }}
                    >
                      {selectedDrugs.includes(drug) ? '✓ ' : ''}{drug}
                    </button>
                  ))}
                </div>
                {selectedDrugs.length > 0 && (
                  <small style={{ color: 'var(--muted)', fontSize: '0.78rem' }}>
                    Selected: {selectedDrugs.join(', ')}
                  </small>
                )}
              </div>

              {/* Notes */}
              <div className="mb-4">
                <label className="form-label fw-semibold" style={{ fontSize: '0.88rem' }}>
                  Additional Notes <span style={{ color: 'var(--muted)' }}>(optional)</span>
                </label>
                <textarea
                  className="form-control form-control-sm"
                  rows={2}
                  placeholder="Any special instructions for the pharmacist..."
                  value={notes}
                  onChange={(e) => setNotes(e.target.value)}
                />
              </div>

              {error && (
                <div className="alert alert-danger py-2 mb-3" style={{ fontSize: '0.82rem' }}>
                  {error}
                </div>
              )}

              {/* Actions */}
              <div style={{ display: 'flex', gap: '0.75rem' }}>
                <button
                  type="submit"
                  style={{
                    backgroundColor: '#198754',
                    color: '#fff',
                    border: 'none',
                    borderRadius: '6px',
                    padding: '0.5rem 1.5rem',
                    fontWeight: 700,
                    fontSize: '0.88rem',
                    cursor: 'pointer',
                    flex: 1,
                  }}
                >
                  Send to Pharmacy →
                </button>
                <button
                  type="button"
                  onClick={onCancel}
                  style={{
                    backgroundColor: '#f8f9fa',
                    color: '#495057',
                    border: '1px solid #dee2e6',
                    borderRadius: '6px',
                    padding: '0.5rem 1rem',
                    fontWeight: 600,
                    fontSize: '0.88rem',
                    cursor: 'pointer',
                  }}
                >
                  Cancel
                </button>
              </div>

            </form>
          </div>
        </div>

        {/* Right — Live Preview */}
        <div className="col-12 col-lg-5">
          <div className="card-custom" style={{ position: 'sticky', top: '80px' }}>
            <h6 style={{ fontWeight: 700, fontSize: '0.9rem', marginBottom: '1rem', color: 'var(--muted)' }}>
              📄 PRESCRIPTION PREVIEW
            </h6>
            <div style={{ fontSize: '0.82rem', lineHeight: 1.8 }}>
              <div><strong>Patient:</strong> {patient.name}</div>
              <div><strong>ID:</strong> {patient.id}</div>
              <div><strong>Doctor:</strong> {doctorName}</div>
              <div><strong>Date:</strong> {new Date().toLocaleDateString('en-GB')}</div>
              <hr />
              <div>
                <strong>Diagnosis:</strong>{' '}
                {diagnosis || <span style={{ color: 'var(--muted)' }}>Not entered yet</span>}
              </div>
              <div style={{ marginTop: '0.5rem' }}>
                <strong>Drugs:</strong>
                {selectedDrugs.length === 0 ? (
                  <span style={{ color: 'var(--muted)' }}> None selected</span>
                ) : (
                  <ul style={{ margin: '0.3rem 0 0 1rem', padding: 0 }}>
                    {selectedDrugs.map((d) => <li key={d}>{d}</li>)}
                  </ul>
                )}
              </div>
              {notes && (
                <div style={{ marginTop: '0.5rem' }}>
                  <strong>Notes:</strong> {notes}
                </div>
              )}
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default NewPrescription;
